package dev.elide.myna.backend;

import dev.elide.myna.model.Seam.*;
import dev.elide.myna.model.Seam.Module;
import java.util.*;

/**
 * Consumer-owned SVM lifecycle integration; no prescribed GC registration or disposal mechanism.
 */
public final class NativeOwnership implements Backend {
  public String filename(Module m) {
    return m.ownershipClass() + ".java";
  }

  public String generate(Module m) {
    var out =
        new StringBuilder(
            "// Generated by myna. Lifecycle implementations are supplied by the consumer.\n"
                + "package "
                + m.javaPackageName()
                + ";\n\npublic final class "
                + m.ownershipClass()
                + " {\n    private "
                + m.ownershipClass()
                + "() {}\n");
    if (!m.resources().isEmpty())
      out.append(
"""
        /** Called exactly once by the consumer when its resource is no longer accessible. */
        @FunctionalInterface
        public interface NativeDestructor { void destroy(long address); }

        /**
         * Takes sole ownership on successful return. On exception, ownership stays with the generator.
         * Must return a non-null owner. Failed adoption must undo registrations without freeing address.
         * The consumer manages GC registration, access guards, and exactly-once destruction.
         * requiredThread is null for shared resources; otherwise access AND destruction require it.
         */
        @FunctionalInterface
        public interface ResourceFactory<T> {
            T adopt(long address, NativeDestructor destructor, java.lang.Thread requiredThread);
        }

""");
    for (Resource r : m.resources()) {
      Function create =
          m.functions().stream().filter(f -> f.name().equals(r.create())).findFirst().orElseThrow();
      var params = new ArrayList<String>();
      var args = new ArrayList<String>();
      // Pointer arguments keep the raw binding's word carriers; scalars are spelled as before.
      for (int i = 0; i < create.parameters().size(); i++) {
        params.add(NativeImage.qualifiedCarrier(create.parameters().get(i).type()) + " arg" + i);
        args.add("arg" + i);
      }
      out.append("    public static final class ")
          .append(r.name())
          .append(" {\n        private ")
          .append(r.name())
          .append("() {}\n")
          .append("        private static final NativeDestructor DESTRUCTOR = address -> ")
          .append(m.nativeClass())
          .append('.')
          .append(r.destroy())
          .append("(org.graalvm.word.WordFactory.pointer(address));\n")
          .append("        /** Null means native creation failed; the consumer is not called. */\n")
          .append("        public static <T> T create(ResourceFactory<T> factory")
          .append(params.isEmpty() ? "" : ", " + String.join(", ", params))
          .append(") {\n")
          .append("            java.util.Objects.requireNonNull(factory);\n")
          .append("            long address = ")
          .append(m.nativeClass())
          .append('.')
          .append(r.create())
          .append('(')
          .append(String.join(", ", args))
          .append(").rawValue();\n")
          .append("            if (address == 0) return null;\n")
          .append("            return adoptUnsafe(address, factory);\n        }\n")
          .append(
              "        /** Transfer sole ownership of a live allocation with no outstanding"
                  + " borrows. */\n")
          .append(
              "        public static <T> T adoptUnsafe(long address, ResourceFactory<T> factory)"
                  + " {\n")
          .append("            java.util.Objects.requireNonNull(factory);\n")
          .append(
              "            if (address == 0) throw new IllegalArgumentException(\"null"
                  + " resource\");\n")
          .append(
              "            try {\n"
                  + "                return java.util.Objects.requireNonNull(factory.adopt(address,"
                  + " DESTRUCTOR, ")
          .append(r.shared() ? "null" : "java.lang.Thread.currentThread()")
          .append(
              "));\n"
                  + "            } catch (RuntimeException | Error failure) {\n"
                  + "                DESTRUCTOR.destroy(address);\n"
                  + "                throw failure;\n"
                  + "            }\n"
                  + "        }\n"
                  + "    }\n");
    }
    if (!m.borrows().isEmpty())
      out.append(
"""
        /**
         * Consumer-owned off-heap bytes. A successful acquire keeps address/size stable and live
         * until release; writable access must be exclusive, read access must prevent mutation.
         * acquire may throw without acquiring; release must not throw. Views may share an owner.
         * A consumer with an externally guaranteed lifetime may implement these hooks as no-ops.
         */
        public interface NativeBuffer {
            void acquire(boolean writable);
            long address();
            long byteSize();
            void release(boolean writable);
        }

""");
    for (CallBorrows call : CallBorrows.of(m)) buffers(m, call, out);
    return out.append("}\n").toString();
  }

  /** One acquired buffer of a wrapper: its positional argument and the suffix of its locals. */
  private record Buffer(String name, String suffix, BufferBorrow borrow) {}

  /**
   * The off-heap and array wrappers of one function. Buffers are acquired or pinned in parameter
   * order and released in reverse, each in a {@code finally} of its own; other parameters pass
   * through in the carriers of the raw binding.
   */
  private static void buffers(Module m, CallBorrows call, StringBuilder out) {
    Function f = call.function();
    // Use positional generated names to avoid collisions with consumer parameter names.
    var nativeParams = new ArrayList<String>();
    var arrayParams = new ArrayList<String>();
    var arguments = new ArrayList<String>();
    var buffers = new ArrayList<Buffer>();
    int index = 0;
    for (Parameter p : f.parameters()) {
      String name = "arg" + index++;
      BufferBorrow buffer = call.buffer(p);
      BufferBorrow length = call.length(p);
      if (buffer != null) {
        buffers.add(new Buffer(name, call.suffix(buffer), buffer));
        nativeParams.add("NativeBuffer " + name);
        arrayParams.add("byte[] " + name);
        arguments.add("pointer" + call.suffix(buffer));
      } else if (length != null)
        arguments.add((call.narrow(length) ? "(int) length" : "length") + call.suffix(length));
      else {
        String carrier = NativeImage.qualifiedCarrier(p.type());
        nativeParams.add(carrier + " " + name);
        arrayParams.add(carrier + " " + name);
        arguments.add(name);
      }
    }
    String invoke =
        (f.returns() == Scalar.VOID ? "" : "return ")
            + m.nativeClass()
            + "."
            + f.name()
            + "("
            + String.join(", ", arguments)
            + ");";
    String returns = Types.java(f.returns());
    out.append("    public static ")
        .append(returns)
        .append(' ')
        .append(f.name())
        .append('(')
        .append(String.join(", ", nativeParams))
        .append(") {\n");
    String pad = "        ";
    for (Buffer b : buffers) {
      String s = b.suffix();
      boolean writable = call.writable(b.borrow());
      out.append(pad)
          .append(b.name())
          .append(".acquire(")
          .append(writable)
          .append(");\n")
          .append(pad)
          .append("try {\n")
          .append(pad)
          .append("    long length")
          .append(s)
          .append(" = ")
          .append(b.name())
          .append(".byteSize();\n");
      if (call.narrow(b.borrow()))
        out.append(pad)
            .append("    if (length")
            .append(s)
            .append(" > ")
            .append(call.maxLength(b.borrow()))
            .append(") throw new IllegalArgumentException(\"buffer length exceeds ABI range\");\n");
      out.append(pad)
          .append("    long address")
          .append(s)
          .append(" = ")
          .append(b.name())
          .append(".address();\n")
          .append(pad)
          .append("    if (length")
          .append(s)
          .append(" < 0 || (address")
          .append(s)
          .append(" == 0 && length")
          .append(s)
          .append(" != 0)) throw new IllegalArgumentException(\"invalid buffer extent\");\n")
          .append(pad)
          .append("    org.graalvm.nativeimage.c.type.CCharPointer pointer")
          .append(s)
          .append(" = address")
          .append(s)
          .append(" == 0\n")
          .append(pad)
          .append(
              "        ? org.graalvm.nativeimage.StackValue.get(1) :"
                  + " org.graalvm.word.WordFactory.pointer(address")
          .append(s)
          .append(");\n");
      pad += "    ";
    }
    out.append(pad).append(invoke).append('\n');
    for (Buffer b : buffers.reversed()) {
      pad = pad.substring(4);
      out.append(pad)
          .append("} finally {\n")
          .append(pad)
          .append("    ")
          .append(b.name())
          .append(".release(")
          .append(call.writable(b.borrow()))
          .append(");\n")
          .append(pad)
          .append("    java.lang.ref.Reference.reachabilityFence(")
          .append(b.name())
          .append(");\n")
          .append(pad)
          .append("}\n");
    }
    out.append("    }\n")
        .append(
            "    /** Array convenience path; caller prevents conflicting concurrent array access."
                + " */\n")
        .append("    public static ")
        .append(returns)
        .append(' ')
        .append(f.name())
        .append('(')
        .append(String.join(", ", arrayParams))
        .append(") {\n");
    // Plain try/finally throughout: try-with-resources compiles to Throwable.addSuppressed, which
    // Truffle's runtime-compilation blocklist rejects on partially evaluated paths (#87).
    if (buffers.size() == 1) {
      String name = buffers.getFirst().name();
      out.append("        long length = ")
          .append(name)
          .append(".length;\n")
          .append(
              "        if (length == 0) {\n"
                  + "            org.graalvm.nativeimage.c.type.CCharPointer pointer ="
                  + " org.graalvm.nativeimage.StackValue.get(1);\n"
                  + "            ")
          .append(invoke)
          .append(f.returns() == Scalar.VOID ? "\n            return;" : "")
          .append("\n        }\n")
          .append(
              "        org.graalvm.nativeimage.PinnedObject pin ="
                  + " org.graalvm.nativeimage.PinnedObject.create(")
          .append(name)
          .append(");\n        try {\n")
          .append(
              "            org.graalvm.nativeimage.c.type.CCharPointer pointer ="
                  + " pin.addressOfArrayElement(0);\n"
                  + "            ")
          .append(invoke)
          .append("\n        } finally {\n            pin.close();\n        }\n    }\n");
      return;
    }
    // Several arrays: every length is read first, then each non-empty array is pinned in turn; an
    // empty one has no element to pin and gets the stack dummy the declared non-null needs.
    for (Buffer b : buffers)
      out.append("        long length")
          .append(b.suffix())
          .append(" = ")
          .append(b.name())
          .append(".length;\n");
    pad = "        ";
    for (Buffer b : buffers) {
      String s = b.suffix();
      out.append(pad)
          .append("org.graalvm.nativeimage.PinnedObject pin")
          .append(s)
          .append(" = length")
          .append(s)
          .append(" == 0 ? null : org.graalvm.nativeimage.PinnedObject.create(")
          .append(b.name())
          .append(");\n")
          .append(pad)
          .append("try {\n")
          .append(pad)
          .append("    org.graalvm.nativeimage.c.type.CCharPointer pointer")
          .append(s)
          .append(" = pin")
          .append(s)
          .append(" == null\n")
          .append(pad)
          .append("        ? org.graalvm.nativeimage.StackValue.get(1) : pin")
          .append(s)
          .append(".addressOfArrayElement(0);\n");
      pad += "    ";
    }
    out.append(pad).append(invoke).append('\n');
    for (Buffer b : buffers.reversed()) {
      pad = pad.substring(4);
      out.append(pad)
          .append("} finally {\n")
          .append(pad)
          .append("    if (pin")
          .append(b.suffix())
          .append(" != null) pin")
          .append(b.suffix())
          .append(".close();\n")
          .append(pad)
          .append("}\n");
    }
    out.append("    }\n");
  }
}
